  "// Server-only complete read. Table pagination and filters never narrow overview totals.\nimport { loadScaffoldRecords } from './scaffold-records.ts';\nimport type { ScaffoldRecord } from './scaffold-contract.ts';\nimport { projectScaffoldOverview, type ScaffoldOverview } from './scaffold-projections.ts';\n\nconst MAX_OVERVIEW_PAGES = 100;\n\n/** Load all records through the credential-aware typed adapter, or return an explicit failure. */\nexport async function loadScaffoldOverview(request: Request, options: { readonly now?: Date; readonly latestLimit?: number } = {}): Promise<ScaffoldOverview> {\n  const url = new URL(request.url);\n  url.search = '';\n  const rows: ScaffoldRecord[] = [];\n  const ids = new Set<string>();\n  let expectedTotal: number | undefined;\n  for (let page = 1; page <= MAX_OVERVIEW_PAGES; page++) {\n    url.searchParams.set('page', String(page));\n    const result = await loadScaffoldRecords(new Request(url, { headers: request.headers, signal: request.signal }));\n    if (result.state !== 'ready' && result.state !== 'empty') return projectScaffoldOverview(result, options);\n    expectedTotal ??= result.total;\n    if (expectedTotal !== result.total || result.rows.some((row) => ids.has(row.id))) break;\n    for (const row of result.rows) { rows.push(row); ids.add(row.id); }\n    if (!result.hasNext) {\n      if (rows.length !== expectedTotal) break;\n      return projectScaffoldOverview({ ...result, state: rows.length ? 'ready' : 'empty', rows }, options);\n    }\n    if (result.rows.length === 0) break;\n  }\n  return { state: 'unavailable', message: 'The complete record summary could not be read. Try again or narrow the service data.' };\n}\n";
