const template_031 =
  "import manifest from '@app/assets/tokens.json' with { type: 'json' };\nimport { appTheme, type AppTheme, themeFontImports, themeLabel } from '@app/lib/theme.ts';\n\ntype PresetId = keyof typeof manifest.presets;\n\n/** Only development design middleware and pages resolve preview presets. */\nexport function designTheme(url: URL): AppTheme & { readonly id: PresetId } {\n  const configured = appTheme();\n  const requested = url.searchParams.get('preset');\n  const candidate = requested && Object.hasOwn(manifest.presets, requested) ? requested : configured.id;\n  if (!Object.hasOwn(manifest.presets, candidate)) throw new Error('Unknown configured token preset');\n  const id = candidate as PresetId;\n  return {\n    id,\n    preset: manifest.presets[id],\n    label: themeLabel(id),\n    fontImports: themeFontImports(id),\n    previewStylesheet: id === configured.id ? undefined : `/presets/${id}.css`,\n  };\n}\n";
const template_032 =
  "import manifest from '@app/assets/tokens.json' with { type: 'json' };\nimport { themeLabel } from '@app/lib/theme.ts';\n\n/** Default metadata is also used by the components gallery. */\nexport const tokenManifestMeta = {\n  version: manifest.version,\n  generatedBy: manifest.generatedBy,\n  total: Object.keys(manifest.tokens).length,\n} as const;\n\n/**\n * One entry from the generated design-token manifest (`assets/tokens.json`).\n */\nexport interface DesignToken {\n  readonly name: string;\n  readonly type: string;\n  readonly value: string;\n  readonly cssVar: string;\n  readonly path: readonly string[];\n}\n\n/** A primitive color ramp (gray, copper, ...) in ascending step order. */\nexport interface ColorRamp {\n  readonly name: string;\n  readonly steps: readonly DesignToken[];\n}\n\n/** A semantic intent (primary, success, ...) with its companion tokens. */\nexport interface SemanticIntent {\n  readonly role: string;\n  readonly tokens: readonly DesignToken[];\n}\n\nconst INTENT_ORDER = [\n  'primary',\n  'secondary',\n  'accent',\n  'success',\n  'warning',\n  'destructive',\n  'info',\n] as const;\n\nconst FOUNDATION_ORDER = [\n  'bg',\n  'fg',\n  'surface',\n  'surface-raised',\n  'overlay',\n  'card',\n  'card-fg',\n  'muted',\n  'muted-fg',\n  'border',\n  'border-hover',\n  'border-strong',\n  'input-border',\n  'ring',\n] as const;\n\n/** Build a request-local projection; static manifest data is never changed. */\nexport function createDesignTokenModel(presetId: keyof typeof manifest.presets) {\n  const preset = manifest.presets[presetId];\n  const values: Readonly<Record<string, string>> = preset.schemes.light;\n  const selected = presetId === manifest.defaultPreset ? manifest.tokens : Object.fromEntries(\n    Object.entries(manifest.definitions).map((\n      [name, token],\n    ) => [name, { ...token, value: values[name] }]),\n  );\n  const allTokens: readonly DesignToken[] = Object.entries(selected).map(([name, token]) => ({\n    name,\n    type: token.type,\n    value: String(token.value),\n    cssVar: token.cssVar,\n    path: token.path,\n  }));\n  const byName = new Map(allTokens.map((token) => [token.name, token]));\n  const tokensIn = (group: string) => allTokens.filter((token) => token.path[0] === group);\n  const rampDefinitions = presetId === manifest.defaultPreset ? manifest.ramps : manifest.allRamps;\n  /** Sorts spacing tokens by their resolved pixel size. */\n  function spaceSize(token: DesignToken): number {\n    if (token.value.endsWith('px')) return Number.parseFloat(token.value);\n    return Number.parseFloat(token.value) * 16;\n  }\n\n  /** Manifest metadata for the page header. */\n  const tokenManifestMeta = {\n    version: manifest.version,\n    generatedBy: manifest.generatedBy,\n    total: allTokens.length,\n  } as const;\n\n  /** Primitive color ramps in display order. */\n  const colorRamps: readonly ColorRamp[] = rampDefinitions.map((ramp) => ({\n    name: ramp.name,\n    steps: ramp.steps.map((name) => byName.get(name)).filter((token): token is DesignToken =>\n      token !== undefined\n    ),\n  }));\n\n  /** Theme-independent semantic foundation tokens (surfaces, text, borders). */\n  const foundationTokens: readonly DesignToken[] = FOUNDATION_ORDER.map(\n    (name) => tokensIn('semantic').find((token) => token.name === name),\n  ).filter((token): token is DesignToken => token !== undefined);\n\n  /** Semantic intents with their full companion sets (base, fg, hover, subtle, border). */\n  const semanticIntents: readonly SemanticIntent[] = INTENT_ORDER.map((role) => ({\n    role,\n    tokens: tokensIn('semantic').filter(\n      (token) => token.name === role || token.name.startsWith(`${role}-`),\n    ),\n  }));\n\n  /** Font family tokens. */\n  const fontTokens: readonly DesignToken[] = tokensIn('font');\n\n  /** Type scale tokens in ascending size order. */\n  const textTokens: readonly DesignToken[] = tokensIn('text');\n\n  /** Line-height tokens. */\n  const leadingTokens: readonly DesignToken[] = tokensIn('leading');\n\n  /** Letter-spacing tokens. */\n  const trackingTokens: readonly DesignToken[] = tokensIn('tracking');\n\n  /** Spacing scale sorted by resolved size. */\n  const spaceTokens: readonly DesignToken[] = [...tokensIn('space')].sort(\n    (a, b) => spaceSize(a) - spaceSize(b),\n  );\n\n  /** Corner radius tokens. */\n  const radiusTokens: readonly DesignToken[] = tokensIn('radius');\n\n  /** Elevation (box-shadow) tokens. */\n  const shadowTokens: readonly DesignToken[] = tokensIn('shadow');\n\n  /** Motion (duration + easing) tokens. */\n  const easeTokens: readonly DesignToken[] = tokensIn('ease');\n\n  /** Z-index scale tokens in stacking order. */\n  const zTokens: readonly DesignToken[] = [...tokensIn('z')].sort(\n    (a, b) => Number.parseFloat(a.value) - Number.parseFloat(b.value),\n  );\n\n  return {\n    presetLabel: themeLabel(presetId),\n    tokenManifestMeta,\n    colorRamps,\n    foundationTokens,\n    semanticIntents,\n    fontTokens,\n    textTokens,\n    leadingTokens,\n    trackingTokens,\n    spaceTokens,\n    radiusTokens,\n    shadowTokens,\n    easeTokens,\n    zTokens,\n  };\n}\n\n/** Presentation data is passed into the view rather than stored in mutable module state. */\nexport type DesignTokenModel = ReturnType<typeof createDesignTokenModel>;\n";
const template_033 =
  "// Query client for the '{{serviceName}}' service. `netscript ui add` (data-bound pages and\n// islands) and `netscript generate resource` select this module by its `…Name` and\n// `…Queries = createQueryFactories(` exports. It can have no importers until a data-bound\n// screen exists; keep it, because deleting it disables those generators.\n\nimport { createServiceClient } from '@netscript/sdk/client';\nimport { createQueryFactories } from '@netscript/sdk/query';\nimport {\n  {{serviceName | pascalCase}}ContractV1,\n} from '@{{name}}/contracts';\n\nexport const {{serviceName | camelCase}}Name = '{{serviceName}}';\nexport const {{serviceName | camelCase}}RouterName = '{{serviceName | camelCase}}';\nexport const {{serviceName | camelCase}}Contract = {{serviceName | pascalCase}}ContractV1;\n\nexport const {{serviceName | camelCase}}Client = createServiceClient<typeof {{serviceName | camelCase}}Contract>({\n  contract: {{serviceName | camelCase}}Contract,\n  serviceName: {{serviceName | camelCase}}Name,\n  routerName: {{serviceName | camelCase}}RouterName,\n});\n\nexport const {{serviceName | camelCase}}Queries = createQueryFactories({\n  {{serviceName | camelCase}}: {\n    contract: {{serviceName | camelCase}}Contract,\n    client: {{serviceName | camelCase}}Client,\n  },\n}).{{serviceName | camelCase}};\n\nexport const {{serviceName | camelCase}}ListInvalidation = { queryKey: {{serviceName | camelCase}}Queries.list.clientKey() } as const;\n";
