  "/**\n * {{appName | pascalCase}} — Fresh application entry point.\n *\n * Uses `defineFreshApp` from `@netscript/fresh/server` so that the\n * baseline bootstrap (static files, fs routes) is framework-managed and\n * consistent with every other NetScript Fresh app. See\n * `apps/playground/main.ts` in the reference monorepo for the same\n * pattern in production use.\n */\n\nimport { defineFreshApp } from '@netscript/fresh/server';\nimport type { State } from '@app/utils.ts';\n\nexport const app = defineFreshApp<State>({ name: '{{appName}}' });\n\n// Startup banner — visible in `aspire start` console logs and local `deno task dev`.\nconst port = parseInt(Deno.env.get('PORT') || '{{appPort}}');\nconst mode = Deno.env.get('MODE') ?? 'development';\n\nconsole.log(`[{{appName}}] starting — ${mode}`);\nconsole.log(`[{{appName}}] listening on http://localhost:${port}`);\nconsole.log(`[{{appName}}] health at http://localhost:${port}/health`);\n";
const template_035 =
  "import { appRoutes, routePatterns } from '@app/router.ts';\n\n/** How a top-bar link decides that it marks the current page. */\nexport type NavigationMatch = 'exact' | 'prefix';\n\n/** One top-bar link rendered by `routes/_layout.tsx`. */\nexport interface NavigationItem {\n  /** Typed href from `appRoutes`. */\n  readonly href: string;\n  /** Visible link text. */\n  readonly label: string;\n  /** `prefix` keeps the link current on nested pages such as `/examples/crud`. */\n  readonly match: NavigationMatch;\n  /** Development reference routes are excluded from production builds. */\n  readonly developmentOnly?: boolean;\n}\n\n/**\n * Top-bar links, in display order. Every page renders inside the app chrome; list a page here to\n * link it. `netscript ui:add page <path>` appends top-level pages for you.\n */\nexport const appNavigation: readonly NavigationItem[] = [\n  { href: appRoutes.dashboard.href(), label: 'Overview', match: 'exact' },\n  { href: appRoutes.records.href(), label: 'Records', match: 'prefix' },\n  { href: appRoutes.settings.href(), label: 'Settings', match: 'exact' },\n  { href: appRoutes.signIn.href(), label: 'Sign in', match: 'exact' },\n  { href: appRoutes.examples.href(), label: 'Examples', match: 'prefix' },\n  { href: appRoutes.health.href(), label: 'Health', match: 'exact' },\n  { href: appRoutes.design.href(), label: 'Design', match: 'prefix', developmentOnly: true },\n];\n\n/**\n * Route prefixes whose pages render their own chrome instead of the app top bar. `/design` ships\n * its own sidebar shell; add a prefix for a full-screen page such as a sign-in screen.\n */\nexport const chromelessRoutePrefixes: readonly string[] = [\n  appRoutes.design.href(),\n  appRoutes.signIn.href(),\n];\n\nfunction isUnderPrefix(pathname: string, prefix: string): boolean {\n  return pathname === prefix || pathname.startsWith(`${prefix}/`);\n}\n\n/** Whether `item` links to the page at `pathname`. */\nexport function isCurrentNavigation(item: NavigationItem, pathname: string): boolean {\n  return item.match === 'exact' ? pathname === item.href : isUnderPrefix(pathname, item.href);\n}\n\n/** Whether the page at `pathname` renders inside the app top bar. */\nexport function rendersAppChrome(pathname: string): boolean {\n  return !chromelessRoutePrefixes.some((prefix) => isUnderPrefix(pathname, prefix));\n}\n\n/** Navigation and command results exclude references unavailable in production. */\nexport function visibleNavigation(): readonly NavigationItem[] {\n  return appNavigation.filter((item) =>\n    !item.developmentOnly || import.meta.env.MODE === 'development'\n  );\n}\n\n/** Count actual page patterns, including nested pages, with the same development filter as navigation. */\nexport function generatedPageCount(): number {\n  const walk = (node: object): number =>\n    Object.entries(node).reduce((count, [key, value]) => {\n      if (key === '$route' && typeof value === 'string') {\n        return count +\n          (value.startsWith('/design') && import.meta.env.MODE !== 'development' ? 0 : 1);\n      }\n      return count + (value && typeof value === 'object' ? walk(value) : 0);\n    }, 0);\n  return walk(routePatterns);\n}\n";
