  "import DesignCompositionView from './(_components)/composition-view.tsx';\nimport { appRoutes } from '@app/router.ts';\nimport { definePage } from '@app/utils.ts';\nimport { designTheme as appTheme } from './(_shared)/theme.ts';\n\nexport const designCompositionPage = definePage()\n  .withRoute(appRoutes.designComposition)\n  .withMeta(() => ({\n    title: 'Composition rules — NetScript design system',\n    description: 'Layering, ownership, and composition rules for scaffolded fresh-ui surfaces.',\n  }))\n  .withLayer('composition', DesignCompositionView, (ctx) => ({ themeLabel: appTheme(ctx.url).label }))\n  .withLayout((slots) => slots.composition())\n  .build();\n\nexport const { default: page } = designCompositionPage;\nexport { page as default };\n";
const template_047 =
  "import type { VNode } from 'preact';\nimport type { ComponentChildren } from 'preact';\nimport { Badge, Button } from '@app/components/ui/mod.ts';\n\nconst SECTIONS = [\n  { id: 'layers', label: 'Layers' },\n  { id: 'ownership', label: 'Ownership' },\n  { id: 'tokens', label: 'Tokens' },\n  { id: 'layout', label: 'Layout objects' },\n  { id: 'attributes', label: 'Attributes' },\n  { id: 'rules', label: 'Do / don’t' },\n] as const;\n\n/** Source: @netscript/fresh-ui L0 layer conventions (§Layer Rules). */\nconst LAYERS = [\n  {\n    id: 'L0',\n    name: 'Platform contract',\n    ownership: 'imported · package-owned',\n    rule:\n      'Token conventions, the data-part / data-state / ARIA rules, and the VisuallyHidden, SrOnly, and Show primitives. Platform elements stay the default — wrappers exist only where they encode behavior or an accessibility contract.',\n  },\n  {\n    id: 'L1',\n    name: 'Runtime behavior',\n    ownership: 'imported · package-owned',\n    rule:\n      'Interactive primitives (accordion, tabs, drawer, tooltip) that centralize keyboard interaction, focus management, and ARIA. L1 emits data attributes, refs, and handlers — never ns-* component classes.',\n  },\n  {\n    id: 'L2',\n    name: 'Registry components',\n    ownership: 'copied · app-owned',\n    rule:\n      'May import L0 or L1, and may emit ns-* classes where the class is the styling contract. An L2 item must not import another L2 item: shared behavior moves down to L0/L1, shared composition moves up to L3.',\n  },\n  {\n    id: 'L3',\n    name: 'Blocks',\n    ownership: 'copied · app-owned',\n    rule:\n      'Compose L2 items and application data seams into dashboard-scale arrangements — page headers, data tables, filter rails.',\n  },\n  {\n    id: 'L4',\n    name: 'Framework integration',\n    ownership: 'yours',\n    rule:\n      'Routes, island wiring, and data loading live in the application, outside @netscript/fresh-ui entirely.',\n  },\n] as const;\n\nconst DOS_AND_DONTS = [\n  {\n    doText: 'Compose new surfaces from Card, Panel, and the layout objects.',\n    dontText: 'Import one L2 component from another (button.tsx inside select.tsx).',\n  },\n  {\n    doText: 'Push behavior two components share down into L0/L1.',\n    dontText: 'Copy-paste keyboard or focus logic between L2 components.',\n  },\n  {\n    doText: 'Express state through semantic intents — Badge variant=’success’.',\n    dontText: 'Hardcode a raw color (#22c55e) because it “looks right” in one theme.',\n  },\n  {\n    doText: 'Reference var(--ns-primary) or a color-mix() of semantic tokens.',\n    dontText: 'Reference a primitive ramp step (--ns-copper-6) from component CSS.',\n  },\n  {\n    doText: 'Reach for native <select>, <dialog>, popover, and <details> first.',\n    dontText: 'Re-implement platform behavior with JavaScript state.',\n  },\n  {\n    doText: 'Edit your ui:add copies freely — after the copy, they are your code.',\n    dontText: 'Wait for a package update to change a copied component.',\n  },\n] as const;\n\nfunction SectionHeading(\n  { id, title, lede }: { id: string; title: string; lede: string },\n): VNode {\n  return (\n    <header class='ns-token-section__head'>\n      <h2 id={id} class='ns-token-section__title'>{title}</h2>\n      <p class='ns-token-section__lede'>{lede}</p>\n    </header>\n  );\n}\n\nfunction LayoutSpecimen(\n  { klass, note, children }: { klass: string; note: string; children: ComponentChildren },\n): VNode {\n  return (\n    <figure class='ns-rules-specimen'>\n      <figcaption class='ns-rules-specimen__cap'>\n        <code>{klass}</code>\n        <span>{note}</span>\n      </figcaption>\n      <div class='ns-rules-specimen__canvas'>{children}</div>\n    </figure>\n  );\n}\n\nfunction Plate({ children }: { children: ComponentChildren }): VNode {\n  return <div class='ns-rules-plate'>{children}</div>;\n}\n\nexport default function DesignCompositionView({ themeLabel }: { themeLabel: string }) {\n  return (\n    <main class='ns-tokens-page'>\n\n      <header class='ns-page-header'>\n        <div class='ns-cluster ns-cluster--md'>\n          <h1>Composition</h1>\n          <Badge variant='primary'>{themeLabel}</Badge>\n          <Badge variant='muted'>L0 contract</Badge>\n        </div>\n        <p class='ns-lede'>\n          How the pieces are allowed to fit together: the layer ladder, who owns which code, what\n          colors components may speak, and the layout vocabulary that holds pages together.\n        </p>\n      </header>\n\n      <div class='ns-tokens-layout'>\n        <nav class='ns-tokens-rail' aria-label='Composition sections'>\n          {SECTIONS.map((section) => (\n            <a key={section.id} href={`#${section.id}`} class='ns-tokens-rail__link'>\n              {section.label}\n            </a>\n          ))}\n        </nav>\n\n        <div class='ns-tokens-sections'>\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='layers'\n              title='The layer ladder'\n              lede='Five layers, one direction of dependency. Anything may import a layer below it; nothing imports sideways or up.'\n            />\n            <ol class='ns-rules-ladder'>\n              {LAYERS.map((layer) => (\n                <li key={layer.id} class='ns-rules-rung'>\n                  <div class='ns-rules-rung__head'>\n                    <span class='ns-rules-rung__id'>{layer.id}</span>\n                    <span class='ns-rules-rung__name'>{layer.name}</span>\n                    <span class='ns-rules-rung__own'>{layer.ownership}</span>\n                  </div>\n                  <p class='ns-rules-rung__rule'>{layer.rule}</p>\n                </li>\n              ))}\n            </ol>\n          </section>\n\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='ownership'\n              title='Two delivery models'\n              lede='The package draws a hard line between code it keeps and code it gives away.'\n            />\n            <div class='ns-rules-pair'>\n              <article class='ns-rules-model'>\n                <h3 class='ns-rules-model__title'>Imported surface</h3>\n                <p class='ns-rules-model__body'>\n                  The root entrypoint exports only the stable helpers safe to keep as runtime\n                  dependencies — <code>cn()</code> and the toast helpers — plus the{' '}\n                  <code>/primitives</code> (L0) and <code>/interactive</code>{' '}\n                  (L1) entry points. This code updates with the package.\n                </p>\n              </article>\n              <article class='ns-rules-model'>\n                <h3 class='ns-rules-model__title'>Copy-source registry</h3>\n                <p class='ns-rules-model__body'>\n                  Every component, block, island, style, and theme item is copy-source.{' '}\n                  <code>ui:add</code>{' '}\n                  writes it into your project and it becomes your code — deliberately, because UI\n                  needs project-specific customization that a stable package API cannot absorb.\n                  Package updates never touch a copy.\n                </p>\n              </article>\n            </div>\n          </section>\n\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='tokens'\n              title='The token rule'\n              lede='Components are theme-blind. NS One is the first theme, not the system.'\n            />\n            <ul class='ns-rules-list'>\n              <li>\n                Component CSS consumes the semantic <code>--ns-*</code> vocabulary and Tailwind{' '}\n                <code>*-ns-*</code> utilities — nothing else.\n              </li>\n              <li>\n                Derived shades come from <code>color-mix()</code>{' '}\n                over semantic tokens, so they re-derive under every theme.\n              </li>\n              <li>\n                Primitive ramp steps are theme raw material: a theme maps them onto roles, and\n                components never reference a ramp directly.\n              </li>\n              <li>\n                Raw color values are allowed only as documented platform fallbacks the vocabulary\n                cannot express.\n              </li>\n              <li>\n                A theme is a generated artifact set — <code>tokens.css</code>,{' '}\n                <code>theme-bridge.css</code>, <code>tokens.json</code>{' '}\n                — produced from a DTCG source. Swap the artifacts and every copied component\n                follows.\n              </li>\n            </ul>\n            <div class='ns-cluster'>\n              <Button type='link' clientNav={false} href='/design/tokens' variant='outline' size='sm'>\n                Token vocabulary\n              </Button>\n              <Button type='link' clientNav={false} href='/design/components' variant='outline' size='sm'>\n                Component gallery\n              </Button>\n            </div>\n          </section>\n\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='layout'\n              title='Layout objects'\n              lede='Theme-independent CSS objects from the layout-objects style item. Blocks and pages compose these instead of inventing one-off flex soup; gaps come from the spacing scale.'\n            />\n            <div class='ns-rules-specimens'>\n              <LayoutSpecimen klass='.ns-stack' note='vertical rhythm; gap via --ns-stack-gap'>\n                <div class='ns-stack ns-stack--sm'>\n                  <Plate>one</Plate>\n                  <Plate>two</Plate>\n                  <Plate>three</Plate>\n                </div>\n              </LayoutSpecimen>\n              <LayoutSpecimen klass='.ns-cluster' note='inline grouping that wraps'>\n                <div class='ns-cluster'>\n                  <Plate>alpha</Plate>\n                  <Plate>beta</Plate>\n                  <Plate>gamma</Plate>\n                  <Plate>delta</Plate>\n                  <Plate>epsilon</Plate>\n                </div>\n              </LayoutSpecimen>\n              <LayoutSpecimen klass='.ns-grid--3' note='fixed three-up grid'>\n                <div class='ns-grid ns-grid--3'>\n                  <Plate>1</Plate>\n                  <Plate>2</Plate>\n                  <Plate>3</Plate>\n                </div>\n              </LayoutSpecimen>\n              <LayoutSpecimen klass='.ns-split' note='two columns that share remaining space'>\n                <div class='ns-split'>\n                  <Plate>main</Plate>\n                  <Plate>aside</Plate>\n                </div>\n              </LayoutSpecimen>\n              <LayoutSpecimen klass='.ns-toolbar' note='action row with grouped ends'>\n                <div class='ns-toolbar'>\n                  <div class='ns-toolbar__group'>\n                    <Plate>filter</Plate>\n                    <Plate>sort</Plate>\n                  </div>\n                  <div class='ns-toolbar__group'>\n                    <Plate>export</Plate>\n                  </div>\n                </div>\n              </LayoutSpecimen>\n              <LayoutSpecimen\n                klass='.ns-switcher'\n                note='columns that stack below --ns-switcher-threshold'\n              >\n                <div class='ns-switcher'>\n                  <Plate>a</Plate>\n                  <Plate>b</Plate>\n                  <Plate>c</Plate>\n                </div>\n              </LayoutSpecimen>\n            </div>\n            <p class='ns-rules-footnote'>\n              Also in the vocabulary: <code>.ns-shell</code>, <code>.ns-section</code>,{' '}\n              <code>.ns-sidebar</code>, <code>.ns-content-rail</code>,{' '}\n              <code>.ns-scroll-region</code>, <code>.ns-cover</code>, <code>.ns-topbar</code>,{' '}\n              <code>.ns-status-bar</code>, and the <code>.ns-dashboard</code>{' '}\n              scaffold this page sits inside.\n            </p>\n          </section>\n\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='attributes'\n              title='Attribute contract'\n              lede='Interactive state is expressed with platform attributes, so styling and behavior stay decoupled.'\n            />\n            <dl class='ns-rules-defs'>\n              <div class='ns-rules-def'>\n                <dt>\n                  <code>data-part</code>\n                </dt>\n                <dd>Names the stable parts of a component — the seams CSS may target.</dd>\n              </div>\n              <div class='ns-rules-def'>\n                <dt>\n                  <code>data-state</code>\n                </dt>\n                <dd>Names visual state (open, checked, loading) without coupling to classes.</dd>\n              </div>\n              <div class='ns-rules-def'>\n                <dt>\n                  <code>aria-*</code>\n                </dt>\n                <dd>Describes accessibility state; it is the contract assistive tech reads.</dd>\n              </div>\n              <div class='ns-rules-def'>\n                <dt>prop getters</dt>\n                <dd>\n                  Event handlers, refs, and attribute bundles come from L1 runtime prop getters —\n                  components spread them, never reimplement them.\n                </dd>\n              </div>\n            </dl>\n            <p class='ns-rules-footnote'>\n              Native first: semantic elements, native form controls, and platform dialog / popover /\n              details behavior before any JavaScript state. Runtime code exists only for what the\n              platform does not provide.\n            </p>\n          </section>\n\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='rules'\n              title='Do / don’t'\n              lede='The ladder, the token rule, and the ownership line — as concrete habits.'\n            />\n            <div class='ns-rules-dodont'>\n              {DOS_AND_DONTS.map((pair) => (\n                <div key={pair.doText} class='ns-rules-dodont__pair'>\n                  <p class='ns-rules-do'>\n                    <span aria-hidden='true'>✓</span>\n                    {pair.doText}\n                  </p>\n                  <p class='ns-rules-dont'>\n                    <span aria-hidden='true'>✕</span>\n                    {pair.dontText}\n                  </p>\n                </div>\n              ))}\n            </div>\n          </section>\n        </div>\n      </div>\n    </main>\n  );\n}\n";
