  "import DesignTokensView from './(_components)/tokens-view.tsx';\nimport { appRoutes } from '@app/router.ts';\nimport { definePage } from '@app/utils.ts';\nimport { designTheme as appTheme } from './(_shared)/theme.ts';\nimport { createDesignTokenModel } from './(_shared)/tokens.ts';\n\nexport const designTokensPage = definePage()\n  .withRoute(appRoutes.designTokens)\n  .withMeta(() => ({\n    title: 'Design tokens — NetScript design system',\n    description: 'Token reference for the scaffolded @netscript/fresh-ui theme.',\n  }))\n  .withLayer(\n    'tokens',\n    DesignTokensView,\n    (ctx) => ({ model: createDesignTokenModel(appTheme(ctx.url).id) }),\n  )\n  .withLayout((slots) => slots.tokens())\n  .build();\n\nexport const { default: page } = designTokensPage;\nexport { page as default };\n";
const template_052 =
  "import type { VNode } from 'preact';\nimport { Badge } from '@app/components/ui/mod.ts';\nimport TokenClipboard from '../(_islands)/TokenClipboard.tsx';\nimport type {\n  ColorRamp,\n  DesignToken,\n  DesignTokenModel,\n  SemanticIntent,\n} from '../(_shared)/tokens.ts';\n\nconst SECTIONS = [\n  { id: 'roles', label: 'Roles' },\n  { id: 'ramps', label: 'Ramps' },\n  { id: 'type', label: 'Type' },\n  { id: 'space', label: 'Space' },\n  { id: 'radius', label: 'Radius' },\n  { id: 'shadow', label: 'Shadow' },\n  { id: 'motion', label: 'Motion' },\n  { id: 'z', label: 'Z-scale' },\n] as const;\n\nconst SPECIMEN = 'Pack my box with five dozen liquor jugs';\n\n/** Copyable `var(--ns-*)` chip; TokenClipboard handles the click. */\nfunction CopyVar({ token }: { token: DesignToken }): VNode {\n  return (\n    <button\n      type='button'\n      class='ns-token-copy'\n      data-token-copy={`var(${token.cssVar})`}\n      title={`Copy var(${token.cssVar})`}\n    >\n      {token.cssVar}\n    </button>\n  );\n}\n\nfunction TokenRow(\n  { token, preview }: { token: DesignToken; preview: VNode },\n): VNode {\n  return (\n    <div class='ns-token-row'>\n      <div class='ns-token-row__preview'>{preview}</div>\n      <CopyVar token={token} />\n      <code class='ns-token-row__value'>{token.value}</code>\n    </div>\n  );\n}\n\nfunction SectionHeading(\n  { id, title, lede }: { id: string; title: string; lede: string },\n): VNode {\n  return (\n    <header class='ns-token-section__head'>\n      <h2 id={id} class='ns-token-section__title'>{title}</h2>\n      <p class='ns-token-section__lede'>{lede}</p>\n    </header>\n  );\n}\n\nfunction FoundationGrid({ tokens }: { tokens: readonly DesignToken[] }): VNode {\n  return (\n    <div class='ns-token-grid'>\n      {tokens.map((token) => (\n        <TokenRow\n          key={token.name}\n          token={token}\n          preview={\n            <span\n              class='ns-token-swatch'\n              style={`background: var(${token.cssVar});`}\n            />\n          }\n        />\n      ))}\n    </div>\n  );\n}\n\nfunction IntentStrip({ intent }: { intent: SemanticIntent }): VNode | null {\n  const base = intent.tokens.find((token) => token.name === intent.role);\n  const fg = intent.tokens.find((token) => token.name === `${intent.role}-fg`);\n  const rest = intent.tokens.filter((token) => token !== base && token !== fg);\n  if (!base || !fg) return null;\n  return (\n    <div class='ns-token-intent'>\n      <button\n        type='button'\n        class='ns-token-intent__hero'\n        style={`background: var(${base.cssVar}); color: var(${fg.cssVar});`}\n        data-token-copy={`var(${base.cssVar})`}\n        title={`Copy var(${base.cssVar})`}\n      >\n        <strong>{intent.role}</strong>\n        <code>{base.cssVar}</code>\n      </button>\n      <div class='ns-token-intent__companions'>\n        {[fg, ...rest].map((token) => (\n          <TokenRow\n            key={token.name}\n            token={token}\n            preview={\n              <span\n                class='ns-token-swatch ns-token-swatch--sm'\n                style={`background: var(${token.cssVar});`}\n              />\n            }\n          />\n        ))}\n      </div>\n    </div>\n  );\n}\n\nfunction RampStrips({ ramps }: { ramps: readonly ColorRamp[] }): VNode {\n  return (\n    <div class='ns-stack ns-stack--lg'>\n      {ramps.map((ramp) => (\n        <figure key={ramp.name} class='ns-token-ramp'>\n          <figcaption class='ns-token-ramp__name'>\n            {ramp.name}\n            <span class='ns-token-ramp__range'>\n              {ramp.steps[0]?.name.split('-').pop()}–{ramp.steps.at(-1)?.name.split('-').pop()}\n            </span>\n          </figcaption>\n          <div class='ns-token-ramp__strip'>\n            {ramp.steps.map((step) => (\n              <button\n                key={step.name}\n                type='button'\n                class='ns-token-ramp__step'\n                style={`background: var(${step.cssVar});`}\n                data-token-copy={`var(${step.cssVar})`}\n                title={`${step.cssVar} · ${step.value}`}\n              >\n                <span class='ns-token-ramp__step-label'>{step.name.split('-').pop()}</span>\n              </button>\n            ))}\n          </div>\n        </figure>\n      ))}\n    </div>\n  );\n}\n\nfunction TypeSpecimens({ model }: { model: DesignTokenModel }): VNode {\n  const { fontTokens, textTokens, leadingTokens, trackingTokens } = model;\n  return (\n    <div class='ns-stack ns-stack--lg'>\n      {fontTokens.map((token) => (\n        <TokenRow\n          key={token.name}\n          token={token}\n          preview={\n            <span\n              class='ns-token-type-specimen'\n              style={`font-family: var(${token.cssVar});`}\n            >\n              {SPECIMEN}\n            </span>\n          }\n        />\n      ))}\n      {textTokens.map((token) => (\n        <TokenRow\n          key={token.name}\n          token={token}\n          preview={\n            <span\n              class='ns-token-type-specimen'\n              style={`font-size: var(${token.cssVar});`}\n            >\n              Scale {token.name.replace('text-', '')}\n            </span>\n          }\n        />\n      ))}\n      {leadingTokens.map((token) => (\n        <TokenRow\n          key={token.name}\n          token={token}\n          preview={\n            <span\n              class='ns-token-type-paragraph'\n              style={`line-height: var(${token.cssVar});`}\n            >\n              {SPECIMEN}, then wraps onto a second line to show its leading.\n            </span>\n          }\n        />\n      ))}\n      {trackingTokens.map((token) => (\n        <TokenRow\n          key={token.name}\n          token={token}\n          preview={\n            <span\n              class='ns-token-type-specimen'\n              style={`letter-spacing: var(${token.cssVar});`}\n            >\n              tracking\n            </span>\n          }\n        />\n      ))}\n    </div>\n  );\n}\n\nfunction SpaceBars({ tokens }: { tokens: readonly DesignToken[] }): VNode {\n  return (\n    <div class='ns-token-grid'>\n      {tokens.map((token) => (\n        <TokenRow\n          key={token.name}\n          token={token}\n          preview={\n            <span class='ns-token-space-track'>\n              <span\n                class='ns-token-space-bar'\n                style={`width: var(${token.cssVar});`}\n              />\n            </span>\n          }\n        />\n      ))}\n    </div>\n  );\n}\n\nfunction RadiusTiles({ tokens }: { tokens: readonly DesignToken[] }): VNode {\n  return (\n    <div class='ns-token-tiles'>\n      {tokens.map((token) => (\n        <TokenRow\n          key={token.name}\n          token={token}\n          preview={\n            <span\n              class='ns-token-radius-tile'\n              style={`border-radius: var(${token.cssVar});`}\n            />\n          }\n        />\n      ))}\n    </div>\n  );\n}\n\nfunction ShadowTiles({ tokens }: { tokens: readonly DesignToken[] }): VNode {\n  return (\n    <div class='ns-token-tiles'>\n      {tokens.map((token) => (\n        <TokenRow\n          key={token.name}\n          token={token}\n          preview={\n            <span\n              class='ns-token-shadow-tile'\n              style={`box-shadow: var(${token.cssVar});`}\n            />\n          }\n        />\n      ))}\n    </div>\n  );\n}\n\nfunction MotionChips({ tokens }: { tokens: readonly DesignToken[] }): VNode {\n  return (\n    <div class='ns-token-tiles'>\n      {tokens.map((token) => (\n        <TokenRow\n          key={token.name}\n          token={token}\n          preview={\n            <span\n              class='ns-token-motion-chip'\n              style={`transition: transform var(${token.cssVar});`}\n            >\n              hover\n            </span>\n          }\n        />\n      ))}\n    </div>\n  );\n}\n\nfunction ZStack({ tokens }: { tokens: readonly DesignToken[] }): VNode {\n  return (\n    <div class='ns-token-zstack'>\n      {tokens.map((token, index) => (\n        <button\n          key={token.name}\n          type='button'\n          class='ns-token-zplate'\n          style={`z-index: var(${token.cssVar}); --zplate-indent: ${index * 2.5}rem;`}\n          data-token-copy={`var(${token.cssVar})`}\n          title={`Copy var(${token.cssVar})`}\n        >\n          <code>{token.cssVar}</code>\n          <span>{token.value}</span>\n        </button>\n      ))}\n    </div>\n  );\n}\n\nexport default function DesignTokensView({ model }: { model: DesignTokenModel }): VNode {\n  const { tokenManifestMeta, semanticIntents, presetLabel } = model;\n  return (\n    <main class='ns-tokens-page'>\n      <TokenClipboard />\n\n      <header class='ns-page-header'>\n        <div class='ns-cluster ns-cluster--md'>\n          <h1>Tokens</h1>\n          <Badge variant='primary'>{presetLabel}</Badge>\n          <Badge variant='muted'>manifest v{tokenManifestMeta.version}</Badge>\n        </div>\n        <p class='ns-lede'>\n          The{' '}\n          {tokenManifestMeta.total}-token vocabulary every component is allowed to speak. Swatches\n          render from the live CSS variables, so this page always shows the active theme. Click any\n          token to copy its variable.\n        </p>\n      </header>\n\n      <div class='ns-tokens-layout'>\n        <nav class='ns-tokens-rail' aria-label='Token sections'>\n          {SECTIONS.map((section) => (\n            <a key={section.id} href={`#${section.id}`} class='ns-tokens-rail__link'>\n              {section.label}\n            </a>\n          ))}\n        </nav>\n\n        <div class='ns-tokens-sections'>\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='roles'\n              title='Semantic roles'\n              lede='What components consume. Surfaces, text, and borders first; the available intents below each pair a base with its fg, hover, subtle, and border companions.'\n            />\n            <FoundationGrid tokens={model.foundationTokens} />\n            <div class='ns-stack ns-stack--lg'>\n              {semanticIntents.map((intent) => <IntentStrip key={intent.role} intent={intent} />)}\n            </div>\n          </section>\n\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='ramps'\n              title='Primitive ramps'\n              lede='Theme raw material. Semantic roles map onto these steps; components never reference a ramp directly.'\n            />\n            <RampStrips ramps={model.colorRamps} />\n          </section>\n\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='type'\n              title='Type'\n              lede='Families, scale, leading, and tracking — each rendered at its own value.'\n            />\n            <TypeSpecimens model={model} />\n          </section>\n\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='space'\n              title='Space'\n              lede='The spacing scale, drawn to size.'\n            />\n            <SpaceBars tokens={model.spaceTokens} />\n          </section>\n\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='radius'\n              title='Radius'\n              lede='Corner rounding, from subtle to full pill.'\n            />\n            <RadiusTiles tokens={model.radiusTokens} />\n          </section>\n\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='shadow'\n              title='Shadow'\n              lede='Elevation steps for raised surfaces and overlays.'\n            />\n            <ShadowTiles tokens={model.shadowTokens} />\n          </section>\n\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='motion'\n              title='Motion'\n              lede='Duration and easing pairs. Hover a chip to feel each curve.'\n            />\n            <MotionChips tokens={model.easeTokens} />\n          </section>\n\n          <section class='ns-token-section'>\n            <SectionHeading\n              id='z'\n              title='Z-scale'\n              lede='The stacking order contract: each layer sits exactly one plate above the last.'\n            />\n            <ZStack tokens={model.zTokens} />\n          </section>\n        </div>\n      </div>\n    </main>\n  );\n}\n";
const template_053 =
  "import {\n  Badge,\n  Button,\n  Card,\n  EmptyState,\n  PageHeader,\n  ResponsiveTable,\n  type ResponsiveTableColumn,\n} from '@app/components/ui/mod.ts';\n\ninterface ExampleCard {\n  readonly title: string;\n  readonly href: string;\n  readonly description: string;\n  readonly status: string;\n  readonly owner: string;\n}\n\ninterface ExamplesViewProps {\n  readonly canonicalHref?: string;\n  readonly examples: readonly ExampleCard[];\n}\n\nconst columns: readonly ResponsiveTableColumn<ExampleCard>[] = [\n  {\n    key: 'title',\n    label: 'Example',\n    priority: 'primary',\n    cell: (example) => example.title,\n  },\n  {\n    key: 'owner',\n    label: 'Owner',\n    cell: (example) => example.owner,\n  },\n  {\n    key: 'status',\n    label: 'Status',\n    cell: (example) => <Badge variant='secondary'>{example.status}</Badge>,\n  },\n  {\n    key: 'action',\n    label: 'Action',\n    align: 'end',\n    cell: (example) => (\n      <Button type='link' href={example.href} variant='ghost' size='sm'>\n        Open\n      </Button>\n    ),\n  },\n];\n\nexport default function ExamplesView({ canonicalHref, examples }: ExamplesViewProps) {\n  return (\n    <div class='workspace-page'>\n      <PageHeader>\n        <PageHeader.Main>\n          <PageHeader.Badges>\n            <Badge variant='primary'>Examples</Badge>\n            <Badge variant='muted'>reference</Badge>\n          </PageHeader.Badges>\n          <PageHeader.Intro>\n            <h1>Examples</h1>\n            <p class='ns-lede'>\n              Reference routes included in this application. Open Records to work with connected data.\n            </p>\n          </PageHeader.Intro>\n          <PageHeader.Actions>\n            {canonicalHref && <Button type='link' href={canonicalHref}>Open {{serviceName}} flow</Button>}\n          </PageHeader.Actions>\n        </PageHeader.Main>\n      </PageHeader>\n\n      <Card>\n        <Card.Header>\n          <Card.Title>Example routes</Card.Title>\n          <Card.Description>Only routes created in this application.</Card.Description>\n        </Card.Header>\n        <Card.Body>\n          <ResponsiveTable\n            caption='Scaffold example routes'\n            columns={columns}\n            rows={examples}\n            getRowKey={(example) => example.href}\n            emptyState={\n              <EmptyState heading='No examples configured'>\n                Add a workflow route and include it in this table.\n              </EmptyState>\n            }\n            summary={<span>{examples.length} examples available</span>}\n          />\n        </Card.Body>\n      </Card>\n    </div>\n  );\n}\n";
const template_054 =
  "import {\n  Badge,\n  Button,\n  Card,\n  DetailLayout,\n  EmptyState,\n  FilterForm,\n  FormField,\n  Input,\n  PageHeader,\n  Panel,\n  ResponsiveTable,\n  type ResponsiveTableColumn,\n  Select,\n  SectionDivider,\n} from '@app/components/ui/mod.ts';\n\ninterface AccountRecord {\n  readonly name: string;\n  readonly plan: string;\n  readonly owner: string;\n  readonly status: 'Active' | 'Review' | 'Paused';\n  readonly updated: string;\n}\n\ninterface CrudExampleViewProps {\n  readonly records: readonly AccountRecord[];\n  readonly serviceHref?: string;\n  readonly recordsHref: string;\n}\n\nconst statusOptions = [\n  { value: 'all', label: 'Any status' },\n  { value: 'active', label: 'Active' },\n  { value: 'review', label: 'Review' },\n  { value: 'paused', label: 'Paused' },\n] as const;\n\nconst columns: readonly ResponsiveTableColumn<AccountRecord>[] = [\n  {\n    key: 'name',\n    label: 'Account',\n    priority: 'primary',\n    cell: (record) => record.name,\n  },\n  {\n    key: 'plan',\n    label: 'Plan',\n    cell: (record) => record.plan,\n  },\n  {\n    key: 'owner',\n    label: 'Owner',\n    cell: (record) => record.owner,\n  },\n  {\n    key: 'status',\n    label: 'Status',\n    cell: (record) => (\n      <Badge\n        variant={record.status === 'Active'\n          ? 'success'\n          : record.status === 'Review'\n          ? 'warning'\n          : 'muted'}\n      >\n        {record.status}\n      </Badge>\n    ),\n  },\n  {\n    key: 'updated',\n    label: 'Updated',\n    align: 'end',\n    cell: (record) => record.updated,\n  },\n];\n\nexport default function CrudExampleView({ records, serviceHref, recordsHref }: CrudExampleViewProps) {\n  const selected = records[0];\n\n  return (\n    <main class='ns-shell ns-section ns-stack ns-stack--lg'>\n      <PageHeader>\n          <PageHeader.Main>\n            <PageHeader.Badges>\n            <Badge variant='primary'>Pattern</Badge>\n            <Badge variant='muted'>static</Badge>\n          </PageHeader.Badges>\n          <PageHeader.Intro>\n            <h1>Directory pattern</h1>\n            <p class='ns-lede'>\n              Static registry form, table, detail, and empty-state blocks for composing app-owned\n              pages. {serviceHref\n                ? <a href={serviceHref}>Open the generated service resource page.</a>\n                : <a href={recordsHref}>Open Records to connect a service.</a>}\n            </p>\n          </PageHeader.Intro>\n          <PageHeader.Actions>\n            <Button>New account</Button>\n            <Button type='link' href='/dashboard' variant='outline'>Dashboard</Button>\n          </PageHeader.Actions>\n        </PageHeader.Main>\n      </PageHeader>\n\n      <FilterForm method='get'>\n        <FilterForm.Body>\n          <FormField label='Search' name='q'>\n            <Input id='q' name='q' placeholder='Account or owner' />\n          </FormField>\n          <FormField label='Status' name='status'>\n            <Select id='status' name='status' options={statusOptions} />\n          </FormField>\n          <FilterForm.Actions>\n            <Button type='submit' variant='secondary'>Apply</Button>\n            <Button type='reset' variant='ghost'>Reset</Button>\n          </FilterForm.Actions>\n        </FilterForm.Body>\n      </FilterForm>\n\n      <DetailLayout>\n        <DetailLayout.Main>\n          <Card>\n            <Card.Header>\n              <Card.Title>Accounts</Card.Title>\n              <Card.Description>Responsive directory table with mobile labels.</Card.Description>\n            </Card.Header>\n            <Card.Body>\n              <ResponsiveTable\n                caption='Accounts'\n                columns={columns}\n                rows={records}\n                getRowKey={(record) => record.name}\n                emptyState={\n                  <EmptyState heading='No accounts match these filters'>\n                    Clear the filters or create a new account record.\n                  </EmptyState>\n                }\n                summary={<span>{records.length} accounts shown</span>}\n              />\n            </Card.Body>\n          </Card>\n        </DetailLayout.Main>\n        <DetailLayout.Aside>\n          <Panel tone='raised'>\n            <Panel.Header>\n              <Panel.Title>{selected?.name ?? 'No account selected'}</Panel.Title>\n              <Panel.Description>Detail rail pattern for edit and audit context.</Panel.Description>\n            </Panel.Header>\n            <Panel.Body>\n              {selected\n                ? (\n                  <div class='ns-stack ns-stack--md'>\n                    <SectionDivider label='Record' />\n                    <dl class='ns-stack ns-stack--sm'>\n                      <div class='ns-cluster ns-cluster--between'>\n                        <dt>Plan</dt>\n                        <dd>{selected.plan}</dd>\n                      </div>\n                      <div class='ns-cluster ns-cluster--between'>\n                        <dt>Owner</dt>\n                        <dd>{selected.owner}</dd>\n                      </div>\n                      <div class='ns-cluster ns-cluster--between'>\n                        <dt>Status</dt>\n                        <dd>{selected.status}</dd>\n                      </div>\n                    </dl>\n                  </div>\n                )\n                : (\n                  <EmptyState heading='Select a record'>\n                    Choose an account to inspect its edit context.\n                  </EmptyState>\n                )}\n            </Panel.Body>\n          </Panel>\n        </DetailLayout.Aside>\n      </DetailLayout>\n    </main>\n  );\n}\n";
